<div class="modal fade" id="modalCampanha"><div class="modal-dialog"><form method="post" action="<?= BASE_URL ?>/index.php?url=indicacaoAdmin/criarCampanha" class="modal-content"><?= \Core\Csrf::input() ?><div class="modal-header"><h5 class="modal-title">Nova campanha</h5></div><div class="modal-body"><div class="form-group"><label>Nome</label><input class="form-control" name="nome" maxlength="120" required></div><div class="form-group"><label>Percentual</label><input class="form-control" name="percentual" type="number" min="0.01" max="100" step="0.01" required></div><div class="form-group"><label>Início</label><input class="form-control" name="data_inicio" type="datetime-local"></div><div class="form-group"><label>Término</label><input class="form-control" name="data_fim" type="datetime-local"></div><div class="custom-control custom-checkbox"><input class="custom-control-input" id="ativa" name="ativo" value="S" type="checkbox"><label class="custom-control-label" for="ativa">Ativa</label></div><div class="custom-control custom-checkbox"><input class="custom-control-input" id="publica" name="publica" value="S" type="checkbox"><label class="custom-control-label" for="publica">Pública</label></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-dismiss="modal">Cancelar</button><button class="btn btn-success">Criar campanha</button></div></form></div></div>
<div class="modal fade" id="modalEditarCampanha"><div class="modal-dialog"><form method="post" action="<?= BASE_URL ?>/index.php?url=indicacaoAdmin/editarCampanha" class="modal-content"><?= \Core\Csrf::input() ?><input type="hidden" name="id" id="editarCampanhaId"><div class="modal-header"><h5 class="modal-title">Editar campanha</h5><button type="button" class="close" data-dismiss="modal" aria-label="Fechar"><span aria-hidden="true">&times;</span></button></div><div class="modal-body"><p class="text-muted small">As alterações valem para configurações futuras e não modificam créditos ou indicações já registrados.</p><div class="form-group"><label for="editarCampanhaNome">Nome</label><input class="form-control" id="editarCampanhaNome" name="nome" maxlength="120" required></div><div class="form-group"><label for="editarCampanhaPercentual">Percentual</label><input class="form-control" id="editarCampanhaPercentual" name="percentual" type="number" min="0.01" max="100" step="0.01" required></div><div class="form-group"><label for="editarCampanhaInicio">Início</label><input class="form-control" id="editarCampanhaInicio" name="data_inicio" type="datetime-local"></div><div class="form-group"><label for="editarCampanhaFim">Término</label><input class="form-control" id="editarCampanhaFim" name="data_fim" type="datetime-local"></div><div class="custom-control custom-checkbox"><input class="custom-control-input" id="editarCampanhaPublica" name="publica" value="S" type="checkbox"><label class="custom-control-label" for="editarCampanhaPublica">Pública</label></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-dismiss="modal">Cancelar</button><button class="btn btn-primary">Salvar alterações</button></div></form></div></div>
<script>$(function(){$('.datatable').DataTable({language:{url:'//cdn.datatables.net/plug-ins/1.13.4/i18n/pt-BR.json'},pageLength:25});$('#modalEditarCampanha').on('show.bs.modal',function(event){var botao=$(event.relatedTarget);$('#editarCampanhaId').val(botao.data('id'));$('#editarCampanhaNome').val(botao.data('nome'));$('#editarCampanhaPercentual').val(botao.data('percentual'));$('#editarCampanhaInicio').val(botao.data('inicio'));$('#editarCampanhaFim').val(botao.data('fim'));$('#editarCampanhaPublica').prop('checked',botao.data('publica')==='S');});});</script>
